import csv
from collections import defaultdict


def load_rows(path):
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows


def sum_by_region(rows):
    tmp = defaultdict(float)
    for row in rows:
        region = row["region"].strip().title()
        amount = float(row["amount"])
        tmp[region] += amount
    return dict(tmp)


def top_regions(rows, n=3):
    tmp = sum_by_region(rows)
    ranked = sorted(tmp.items(), key=lambda kv: kv[1], reverse=True)
    return ranked[:n]


def monthly_totals(rows):
    tmp = defaultdict(float)
    for row in rows:
        month = row["date"][:7]
        tmp[month] += float(row["amount"])
    return dict(sorted(tmp.items()))


def report(path):
    rows = load_rows(path)
    tmp = top_regions(rows)
    for region, amount in tmp:
        print(f"{region:<12} {amount:>10.2f}")
    for month, amount in monthly_totals(rows).items():
        print(f"{month}  {amount:>10.2f}")


if __name__ == "__main__":
    report("sales.csv")
